const fs = require('fs');

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
let l = BigInt(input[0]);
let r = BigInt(input[1]);

const w = [];
const W = [];

while (l > 0) {
    w.push(l & 1n);
    l >>= 1n;
}
while (r > 0) {
    W.push(r & 1n);
    r >>= 1n;
}

let p = 0;
const maxLen = Math.max(w.length, W.length);
for (let i = maxLen - 1; i >= 0; i--) {
    const bitW = w[i] || 0n;
    const bitR = W[i] || 0n;
    if (bitW !== bitR) {
        p = i + 1;
        break;
    }
}

const ans = (1n << BigInt(p)) - 1n;
console.log(ans.toString());

